    var CATEGORIES = ['temps', 'fetes', 'priere', 'objets', 'personnes', 'communautes', 'etude', 'loi', 'croyances', 'temple', 'alimentation', 'terre', 'cycle', 'purete'];

    function list(s) { return s ? s.split(',').map(function (x) { return x.trim(); }).filter(Boolean) : []; }

